components.css:
.ds-machine {
	width: min(430px, 70vw);
	height: 330px;
	position: relative;
	display: grid;
	place-items: center;
	perspective: 850px;
}

.ds-machine__orbit {
	position: absolute;
	inset: 14px 34px 26px;
	border: 1px dashed #343833;
	border-radius: 50%;
	animation: orbit 18s linear infinite;
}

.ds-machine__orbit span {
	position: absolute;
	padding: 3px 8px;
	background: var(--ink);
	color: #52574f;
	font: 700 9px/1 "Space Grotesk Variable", sans-serif;
	letter-spacing: 0.12em;
}

.ds-machine__orbit span:nth-child(1) { left: 12%; top: 7%; }
.ds-machine__orbit span:nth-child(2) { right: -2%; top: 47%; }
.ds-machine__orbit span:nth-child(3) { left: 34%; bottom: -2%; }

.ds-machine__shadow {
	position: absolute;
	width: 230px;
	height: 25px;
	bottom: 36px;
	border-radius: 50%;
	background: #000;
	filter: blur(11px);
	opacity: 0.8;
	transform: scaleX(1);
	transition: transform 500ms ease, opacity 500ms ease;
}

.ds-crate {
	width: 244px;
	height: 190px;
	position: relative;
	transform-style: preserve-3d;
	animation: breathe 3.4s ease-in-out infinite;
}

.ds-crate__body {
	position: absolute;
	left: 0;
	right: 0;
	bottom: 0;
	height: 148px;
	background: #303b31;
	border: 4px solid #0c0e0c;
	box-shadow:
		inset 0 0 0 2px #627062,
		12px 16px 0 #050605;
	clip-path: polygon(0 0, 100% 0, 100% 86%, 91% 100%, 9% 100%, 0 86%);
	overflow: hidden;
}

.ds-crate__body::before,
.ds-crate__body::after {
	content: "";
	position: absolute;
	top: 0;
	bottom: 0;
	width: 24px;
	background: #171c18;
	border-inline: 2px solid #4c584d;
}

.ds-crate__body::before { left: 20px; }
.ds-crate__body::after { right: 20px; }

.ds-crate__lid {
	position: absolute;
	left: -7px;
	top: 12px;
	width: 258px;
	height: 64px;
	background: #3d493e;
	border: 4px solid #0c0e0c;
	box-shadow: inset 0 0 0 2px #687668, 12px 10px 0 #050605;
	z-index: 5;
	transform-origin: 50% 100%;
	transform-style: preserve-3d;
	transition: transform 850ms cubic-bezier(0.17, 0.89, 0.24, 1.3), filter 500ms ease;
}

.ds-crate__lid-panel {
	display: flex;
	align-items: center;
	justify-content: center;
	gap: 12px;
	height: 100%;
	color: var(--lime);
	font: 400 13px/1 Bungee, sans-serif;
	letter-spacing: 0.07em;
}

.ds-crate__hazard {
	position: absolute;
	inset: 8px 52px auto;
	height: 11px;
	background-color: var(--orange);
	background-image: url("data:image/svg+xml,%3Csvg width='24' height='12' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M-2 12L10 0h8L6 12zm24 0L34 0h8L30 12z' fill='%23171c18'/%3E%3C/svg%3E");
}

.ds-crate__mark {
	position: absolute;
	inset: 42px 54px 25px;
	display: flex;
	flex-direction: column;
	align-items: center;
	justify-content: center;
	border: 1px solid #687668;
	background: #222923;
	z-index: 2;
}

.ds-crate__mark span {
	font-size: 9px;
	letter-spacing: 0.25em;
	color: #8f9a8e;
}

.ds-crate__mark strong {
	font: 400 15px/1.4 Bungee, sans-serif;
	color: var(--paper);
}

.ds-crate__rivet {
	position: absolute;
	width: 7px;
	height: 7px;
	border-radius: 50%;
	background: #8e998e;
	box-shadow: inset 2px 2px #d2d7cb;
	z-index: 3;
}

.ds-crate__rivet--a { top: 12px; left: 8px; }
.ds-crate__rivet--b { top: 12px; right: 8px; }
.ds-crate__rivet--c { bottom: 19px; left: 8px; }
.ds-crate__rivet--d { bottom: 19px; right: 8px; }

.ds-crate__light {
	position: absolute;
	left: 24px;
	right: 24px;
	top: 71px;
	height: 6px;
	background: var(--lime);
	box-shadow: 0 0 18px var(--lime);
	z-index: 4;
	opacity: 0.75;
	transition: opacity 300ms ease, transform 300ms ease;
}

.ds-machine__core {
	position: absolute;
	width: 112px;
	height: 112px;
	display: grid;
	place-items: center;
	color: var(--ink);
	background: var(--lime);
	border-radius: 50%;
	box-shadow: 0 0 20px var(--lime), 0 0 70px #c9ff4388;
	opacity: 0;
	transform: scale(0.15);
	transition: opacity 250ms ease, transform 650ms cubic-bezier(0.17, 0.89, 0.32, 1.49);
}


.ds-machine{font-family:"Space Grotesk Variable",sans-serif}.ds-machine__orbit{animation:none}.ds-machine__orbit span{color:#85917c}.ds-crate{animation:none}.ds-crate__mark span{letter-spacing:.03em;font-size:7px}@media(prefers-reduced-motion:reduce){.ds-machine *{animation:none!important;transition:none!important}}
